import { Input as InputPrimitive } from '@base-ui/react/input';
import type { ComponentProps } from 'react';

import { cn } from '@/lib/utils';

function Input({ className, type, ...props }: ComponentProps<'input'>) {
  return (
    <InputPrimitive
      type={type}
      data-slot="input"
      className={cn(
        'h-12 w-full min-w-0 rounded-sm border border-input bg-card px-3 py-2 text-base transition-colors outline-none file:inline-flex file:h-8 file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:bg-background',
        className,
      )}
      {...props}
    />
  );
}

export { Input };

import type { ComponentProps, ComponentType } from 'react';

import { Input } from '@/registry/frontend-ui/input/ui/input';
import { cn } from '@/lib/utils';

interface InputIconProps extends ComponentProps<typeof Input> {
  icon: ComponentType<{ className?: string }>;
}

function InputIcon({ icon: Icon, className, ...props }: InputIconProps) {
  return (
    <div className="relative">
      <Icon className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground" />
      <Input className={cn('pl-10', className)} {...props} />
    </div>
  );
}

export { InputIcon };
